944	/** 生成每日一句话总结 */
945	function generateDailySummary(state, startCash, startHealth, startHappiness) {
946	  var cash = state.resources.cash || 0;
947	  var bank = state.resources.bankBalance || 0;
948	  var delta = cash - startCash;
949	  var healthDrop = startHealth - ((state.status && state.status.health) || 100);
950	  var happyDrop =
951	    startHappiness - ((state.needs && state.needs.happiness) || 0);
952	  var day = state.player.day || 1;
953	
954	  var highlights = [];
955	
956	  // 特殊叙事片段（优先级最高）
957	  if (state.flags._todayDeepTaskDone) {
958	    highlights.push("有个人在你心里留下了什么");
959	  } else if (state.flags._todayDebtEvent) {
960	    highlights.push("村长的钱，又压了一整天");
961	  } else if (state.flags._todayMentalEvent) {
962	    highlights.push("心里那根弦今天绷得很紧");
963	  }
964	
965	  // 财务总结（分更多档次，语气有温度）
966	  if (delta >= 1000) {
967	    highlights.push("今天是个好日子，净赚了¥" + delta.toLocaleString());
968	  } else if (delta >= 300) {
969	    highlights.push("今天赚了¥" + delta.toLocaleString() + "，还不错");
970	  } else if (delta >= 50) {
971	    highlights.push("今天净入¥" + delta.toLocaleString() + "，比昨天强点");
972	  } else if (delta >= 0) {
973	    highlights.push("今天收支基本持平，活下来了");
974	  } else if (delta < -500) {
975	    highlights.push("今天支出不少，净亏了¥" + Math.abs(delta).toLocaleString());
976	  } else if (delta < 0) {
977	    highlights.push(
978	      "今天支出略多，口袋瘦了¥" + Math.abs(delta).toLocaleString(),
979	    );
980	  }
981	
982	  // 里程碑叙事
983	  if (day === 7) highlights.push("来这座城市整整一周了");
984	  else if (day === 30) highlights.push("整整一个月，你还在");
985	  else if (day === 100) highlights.push("百天了，城市没把你打倒");
986	  else if (day === 365) highlights.push("一年了，从头到今天");
987	
988	  // 存款鼓励
989	  if (bank >= 10000 && highlights.length < 2) {
990	    highlights.push("银行里¥" + bank.toLocaleString() + "，是你在这城市的底气");
991	  } else if (bank > 0 && highlights.length < 2) {
992	    highlights.push("银行里的¥" + bank.toLocaleString() + "还在生息");
993	  }
994	
995	  // 健康/心情状态
996	  if (healthDrop >= 15) {
997	    highlights.push("身体吃不消了，明天注意");
998	  } else if (happyDrop >= 20) {
999	    highlights.push("今天过得不太开心，明天找找乐子");
1000	  }
1001	
1002	  // 村长债务提示（仅经典模式/有 villageDebt 的剧本）
1003	  if ((state.resources.villageDebt || 0) > 0 && highlights.length < 2) {
1004	    highlights.push(
1005	      "村长那¥" +
1006	        (state.resources.villageDebt || 0).toLocaleString() +
1007	        "的债还压着呢",
1008	    );
1009	  }
1010	
1011	  // 节日氛围
1012	  if (typeof getCurrentFestival === "function") {
1013	    var fest = getCurrentFestival(day);
1014	    if (fest && highlights.length < 2)
1015	      highlights.push(fest.icon + " " + fest.name + "的气氛越来越浓了");
1016	  }
1017	
1018	  // 梦想进度
1019	  if (typeof getDreamProgress === "function" && highlights.length < 2) {
1020	    var dp = getDreamProgress(state);
1021	    if (dp > 0 && dp < 100) highlights.push("梦想进度" + dp + "%，一直往前");
1022	  }
1023	
1024	  // 清除今日临时标记
1025	  delete state.flags._todayDeepTaskDone;
1026	  delete state.flags._todayDebtEvent;
1027	  delete state.flags._todayMentalEvent;
1028	
1029	  if (!highlights.length) highlights.push("平凡的一天，活着就是赢了");
1030	
1031	  var summary = highlights.slice(0, 2).join("，") + "。";
1032	  return "📋 今日总结：" + summary;
1033	}
1034	
1035	/**
1036	 * 执行每日结算管线。
1037	 * 遍历所有步骤，遇到极端状态('skip_day')时短路。
1038	 * MiniMax 友好：新增步骤只需 push 一个 {name, fn} 对象。
1039	 */
1040	function runDailyPipeline(state) {
1041	  // 记录日始状态用于今日总结
1042	  // v3.2 修复: _dayStartCash 在 day_increment 步骤中设置（正确捕获日初现金）
1043	  // 此处仅记录健康/心情日始值（这些在管线中不变化）
1044	  state.flags._dayStartHealth = (state.status && state.status.health) || 100;
1045	  state.flags._dayStartHappiness = (state.needs && state.needs.happiness) || 0;
1046	
1047	  for (var i = 0; i < DAILY_PIPELINE.length; i++) {
1048	    var step = DAILY_PIPELINE[i];
1049	
1050	    // 极端状态短路逻辑：
1051	    // extreme_check / critical_punish 返回 'skip_day' 时，跳过后续非核心步骤
1052	    // 但 finance / autosave / daily_report 始终执行
1053	    // （v3.0 修复：daily_report 也加入始终执行列表，否则极端状态天玩家看不到收支报告）
1054	    if (step.name === "extreme_check" || step.name === "critical_punish") {
1055	      var result = step.fn(state);
1056	      if (result === "skip_day") {
1057	        StateManager.addMessage(
1058	          "🌙 第" + state.player.day + "天在昏迷中过去了...",
1059	          "danger",
1060	        );
1061	        // 执行最后的核心步骤：财务、收支报告、存档
1062	        for (var j = i + 1; j < DAILY_PIPELINE.length; j++) {
1063	          var lateStep = DAILY_PIPELINE[j];
1064	          if (
1065	            lateStep.name === "finance" ||
1066	            lateStep.name === "autosave" ||
1067	            lateStep.name === "daily_report"
1068	          ) {
1069	            lateStep.fn(state);
1070	          }
1071	        }
1072	        return; // 短路
1073	      }
1074	    } else {
1075	      step.fn(state);
1076	    }
1077	  }
1078	}
1079	
1080	/**
1081	 * endDay — 仅保留管线调度逻辑（MiniMax 友好：170行→8行）
1082	 */
1083	function endDay() {
1084	  var state = StateManager.getState();
1085	  runDailyPipeline(state);
1086	}
